package com.tabletportals;

import java.awt.Color;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * One-shot effects (smoke puffs, the tablet shattering) built from the game's own graphics and drawn in the
 * world like any spell effect, optionally recoloured.
 */
@Singleton
class Effects
{
	private static final Logger log = LoggerFactory.getLogger(Effects.class);

	/** Cache archive holding graphic (spotanim) definitions. */
	private static final int SPOTANIM_ARCHIVE = 13;

	private static final int AMBIENT = 64;
	private static final int CONTRAST = 850;

	private final Client client;
	private final Map<Integer, GraphicDef> graphics = new HashMap<>();
	/** Graphics that couldn't be read, so we don't keep trying every time. */
	private final Map<Integer, Boolean> broken = new HashMap<>();
	private final List<RuneLiteObject> active = new ArrayList<>();

	@Inject
	Effects(Client client)
	{
		this.client = client;
	}

	/**
	 * Plays a graphic once at a spot.
	 *
	 * @param height how far above the ground, in local units
	 * @param color  tint, or null for the graphic's own colours
	 */
	void play(int graphicId, LocalPoint at, int plane, int height, int orientation, Color color)
	{
		GraphicDef g = graphic(graphicId);
		if (g == null || at == null || g.animation < 0)
		{
			return;
		}
		ModelData md = client.loadModelData(g.model);
		Animation anim = client.loadAnimation(g.animation);
		if (md == null || anim == null)
		{
			return;
		}

		md = md.shallowCopy().cloneColors();
		if (g.recolorFind != null)
		{
			for (int i = 0; i < Math.min(g.recolorFind.length, g.recolorReplace.length); i++)
			{
				md.recolor(g.recolorFind[i], g.recolorReplace[i]);
			}
		}
		if (g.retextureFind != null)
		{
			md = md.cloneTextures();
			for (int i = 0; i < Math.min(g.retextureFind.length, g.retextureReplace.length); i++)
			{
				md.retexture(g.retextureFind[i], g.retextureReplace[i]);
			}
		}
		for (int i = 0; i < Math.floorMod(g.rotation, 360) / 90; i++)
		{
			md = md.cloneVertices().rotateY90Ccw();
		}
		if (g.resizeX != 128 || g.resizeY != 128)
		{
			md = md.cloneVertices().scale(g.resizeX, g.resizeY, g.resizeX);
		}
		GraphicDef.tint(md, color);

		Model model = md.light(AMBIENT + g.ambient, CONTRAST + g.contrast, -30, -50, -30);
		if (model == null)
		{
			return;
		}

		RuneLiteObject obj = client.createRuneLiteObject();
		obj.setModel(model);
		obj.setLocation(at, plane);
		obj.setZ(Perspective.getTileHeight(client, at, plane) - height);
		obj.setOrientation(orientation);
		AnimationController once = new AnimationController(client, anim);
		once.setOnFinished(ac -> obj.setActive(false)); // one-shot: gone when the animation ends
		obj.setAnimationController(once);
		obj.setActive(true);
		active.add(obj);
	}

	/** Forgets finished effects. Call every client tick. */
	void tick()
	{
		for (Iterator<RuneLiteObject> it = active.iterator(); it.hasNext(); )
		{
			if (!it.next().isActive())
			{
				it.remove();
			}
		}
	}

	void clear()
	{
		for (RuneLiteObject o : active)
		{
			o.setActive(false);
		}
		active.clear();
	}

	GraphicDef graphic(int id)
	{
		GraphicDef cached = graphics.get(id);
		if (cached != null || broken.containsKey(id))
		{
			return cached;
		}
		IndexDataBase configs = client.getIndexConfig();
		byte[] data = configs == null ? null : configs.loadData(SPOTANIM_ARCHIVE, id);
		if (data == null)
		{
			return null; // cache not ready yet; try again later
		}
		try
		{
			GraphicDef g = GraphicDef.decode(data);
			if (g != null)
			{
				graphics.put(id, g);
			}
			else
			{
				broken.put(id, true);
			}
			return g;
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read graphic {}", id, e);
			broken.put(id, true);
			return null;
		}
	}
}

package com.tabletportals;

/**
 * Directions from the game's orientation angle: 2048 units to a full turn, 0 facing south, 512 west,
 * 1024 north and 1536 east. Local x grows to the east and y to the north.
 */
final class Facing
{
	private Facing()
	{
	}

	/** The step, in local units, {@code distance} ahead of something facing {@code orientation}. */
	static int[] ahead(int orientation, int distance)
	{
		double a = (orientation & 2047) * Math.PI * 2 / 2048;
		return new int[]{
			(int) Math.round(-Math.sin(a) * distance),
			(int) Math.round(-Math.cos(a) * distance),
		};
	}

	/** The step {@code distance} to the right of something facing {@code orientation}. */
	static int[] right(int orientation, int distance)
	{
		// Facing south, your right hand is to the west.
		return ahead(orientation + 512, distance);
	}
}

package com.tabletportals;

import java.awt.Color;
import net.runelite.api.JagexColor;
import net.runelite.api.ModelData;

/**
 * A graphic (spotanim) definition read from the game cache, so its model can be drawn as a
 * {@link net.runelite.api.RuneLiteObject} anywhere, and recoloured. The opcode layout follows the game's
 * cache format; the handling of opcode 10 (a flag with no data) is from Rapid Mounts by RapidUrsa
 * (BSD 2-Clause, see THIRD_PARTY_NOTICES.md).
 */
final class GraphicDef
{
	int model;
	int animation = -1;
	int resizeX = 128;
	int resizeY = 128;
	int rotation;
	int ambient;
	int contrast;
	short[] recolorFind;
	short[] recolorReplace;
	short[] retextureFind;
	short[] retextureReplace;

	static GraphicDef decode(byte[] data)
	{
		Reader in = new Reader(data);
		GraphicDef g = new GraphicDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			switch (op)
			{
				case 1:
					g.model = in.u16();
					break;
				case 2:
					g.animation = in.u16();
					break;
				case 3:
					g.model = in.i32();
					break;
				case 4:
					g.resizeX = in.u16();
					break;
				case 5:
					g.resizeY = in.u16();
					break;
				case 6:
					g.rotation = in.u16();
					break;
				case 7:
					g.ambient = in.u8();
					break;
				case 8:
					g.contrast = in.u8();
					break;
				case 9:
					in.skipString();
					break;
				case 10:
					break;
				case 40:
				{
					int n = in.u8();
					g.recolorFind = new short[n];
					g.recolorReplace = new short[n];
					for (int i = 0; i < n; i++)
					{
						g.recolorFind[i] = (short) in.u16();
						g.recolorReplace[i] = (short) in.u16();
					}
					break;
				}
				case 41:
				{
					int n = in.u8();
					g.retextureFind = new short[n];
					g.retextureReplace = new short[n];
					for (int i = 0; i < n; i++)
					{
						g.retextureFind[i] = (short) in.u16();
						g.retextureReplace[i] = (short) in.u16();
					}
					break;
				}
				case 42:
					in.u16(); // whole-model recolour; not needed here
					break;
				default:
					throw new IllegalStateException("unknown graphic opcode " + op);
			}
		}
		return g.model > 0 ? g : null;
	}

	/**
	 * Recolours every face to the given colour's hue and saturation, keeping each face's own lightness,
	 * so the model keeps its shading and just changes colour. Does nothing for a null colour.
	 */
	static void tint(ModelData md, Color color)
	{
		if (color == null)
		{
			return;
		}
		short[] colors = md.getFaceColors();
		if (colors == null)
		{
			return;
		}
		short target = JagexColor.rgbToHSL(color.getRGB(), 1.0);
		int hue = JagexColor.unpackHue(target);
		int sat = JagexColor.unpackSaturation(target);
		for (int i = 0; i < colors.length; i++)
		{
			colors[i] = tintColor(colors[i], hue, sat);
		}
	}

	static short tintColor(short hsl, int hue, int sat)
	{
		return JagexColor.packHSL(hue, sat, JagexColor.unpackLuminance(hsl));
	}

	private static final class Reader
	{
		private final byte[] data;
		private int pos;

		Reader(byte[] data)
		{
			this.data = data;
		}

		int u8()
		{
			return data[pos++] & 0xFF;
		}

		int u16()
		{
			return (u8() << 8) | u8();
		}

		int i32()
		{
			return (u16() << 16) | u16();
		}

		void skipString()
		{
			while (data[pos++] != 0)
			{
				// skip to the terminating zero
			}
		}
	}
}

package com.tabletportals;

import java.awt.Color;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;

/**
 * The swirling portal: the game's own portal swirl (the one inside house and Clan Wars portals), standing on
 * its own without a frame, with its spinning animation. It can grow and shrink; the sizes are built ahead of
 * time so nothing is rebuilt while it animates.
 */
final class Portal
{
	/** The portal swirl model, and its spin animation, as used by the house portal objects. */
	static final int SWIRL_MODEL = 11233;
	static final int SWIRL_ANIMATION = 3174;

	/** The swirl model spans y -315..-55 (up is negative) and sits at z -37..-21; its middle is here. */
	private static final int MODEL_CENTRE_Y = -185;
	private static final int MODEL_CENTRE_Z = -29;
	private static final int MODEL_HALF_HEIGHT = 130;
	/** At 100% size the swirl is 0.9x the game's own: 234 units tall, a little taller than a player. */
	private static final float BASE_SCALE = 0.9f;
	/** How high the bottom edge floats above the ground once fully open. */
	private static final int HOVER = 30;

	/** The sizes (fractions of fully open) that are built; the nearest is shown. */
	static final float[] STEPS = {0.05f, 0.12f, 0.2f, 0.3f, 0.4f, 0.5f, 0.6f, 0.7f, 0.8f, 0.9f, 1f, 1.06f, 1.12f};

	private final RuneLiteObject obj;
	private final Model[] models = new Model[STEPS.length];
	private int shown = -1;
	/** Scale of the fully open swirl against the game's own. */
	private float full;
	/** Current size, 0 (gone) to 1 (fully open). */
	private float size;

	private Portal(RuneLiteObject obj)
	{
		this.obj = obj;
	}

	/** Builds a portal, or returns null if the game hasn't loaded the models yet. */
	static Portal build(Client client, Color tint, int sizePercent)
	{
		ModelData base = client.loadModelData(SWIRL_MODEL);
		Animation spin = client.loadAnimation(SWIRL_ANIMATION);
		if (base == null)
		{
			return null;
		}
		base = base.shallowCopy().cloneColors();
		GraphicDef.tint(base, tint);

		float full = BASE_SCALE * sizePercent / 100f;
		// Once open, the middle of the swirl sits here, so it hovers just above the ground at any size.
		int centreY = -Math.round(HOVER + MODEL_HALF_HEIGHT * full);

		RuneLiteObject obj = client.createRuneLiteObject();
		Portal p = new Portal(obj);
		p.full = full;
		for (int i = 0; i < STEPS.length; i++)
		{
			int k = Math.max(1, Math.round(128 * full * STEPS[i]));
			ModelData md = base.shallowCopy().cloneVertices()
				.translate(0, -MODEL_CENTRE_Y, -MODEL_CENTRE_Z) // centre the swirl on the origin
				.scale(k, k, k) // grow from the middle
				.translate(0, centreY, 0);
			p.models[i] = md.light(ModelData.DEFAULT_AMBIENT, ModelData.DEFAULT_CONTRAST,
				ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
			if (p.models[i] == null)
			{
				return null;
			}
		}
		obj.setModel(p.models[0]);
		if (spin != null)
		{
			obj.setAnimation(spin); // loops by default
		}
		return p;
	}

	static int nearestStep(float size)
	{
		int best = 0;
		for (int i = 1; i < STEPS.length; i++)
		{
			if (Math.abs(STEPS[i] - size) < Math.abs(STEPS[best] - size))
			{
				best = i;
			}
		}
		return best;
	}

	/** Puts the portal at a spot, facing the same way as whoever walks into (or out of) it. */
	void place(LocalPoint at, int plane, int orientation)
	{
		obj.setLocation(at, plane);
		obj.setOrientation(orientation);
	}

	/** Shows the portal at a size from 0 (gone) to 1 (fully open), a little over 1 for the pop. */
	void setSize(float size)
	{
		this.size = size;
		if (size < 0.03f)
		{
			obj.setActive(false);
			shown = -1;
			return;
		}
		int i = nearestStep(size);
		if (i != shown)
		{
			obj.setModel(models[i]);
			shown = i;
		}
		if (!obj.isActive())
		{
			obj.setActive(true);
		}
	}

	void remove()
	{
		obj.setActive(false);
		shown = -1;
		size = 0;
	}

	/** Current size, 0 (gone) to 1 (fully open). */
	float getSize()
	{
		return obj.isActive() ? size : 0f;
	}

	/** Radius of the swirl at its current size, in local units. */
	float radius()
	{
		return MODEL_HALF_HEIGHT * full * getSize();
	}

	/** Height of the swirl's middle above the ground, in local units. It grows from here. */
	int centreHeight()
	{
		return Math.round(HOVER + MODEL_HALF_HEIGHT * full);
	}

	LocalPoint location()
	{
		return obj.getLocation();
	}
}

package com.tabletportals;

import java.awt.Color;

/** The colour of the portal's swirl. Classic keeps the game's own purple. */
public enum PortalColour
{
	CLASSIC("Classic purple", null),
	ARCANE("Arcane blue", new Color(70, 140, 255)),
	EMERALD("Emerald", new Color(40, 200, 110)),
	INFERNO("Inferno", new Color(255, 90, 30)),
	GOLDEN("Golden", new Color(255, 200, 50)),
	VOID("Void", new Color(60, 60, 70)),
	CUSTOM("Custom", null);

	private final String label;
	private final Color color;

	PortalColour(String label, Color color)
	{
		this.label = label;
		this.color = color;
	}

	/** The tint for this choice, or null to keep the original colours. */
	Color resolve(Color custom)
	{
		return this == CUSTOM ? custom : color;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.tabletportals;

import net.runelite.api.Player;

/**
 * Makes a player walk on the spot, on your screen only, by swapping all their movement animations for their
 * walk, and puts them back afterwards. The walking copy drawn by {@link Walker} takes its model from the
 * player, so this is what makes the copy's legs move.
 */
final class Poser
{
	/** The player's own movement animations while posed, or null. */
	private int[] saved;
	private int walk = -1;

	boolean isPosed()
	{
		return saved != null;
	}

	/** Starts walking on the spot. Cheap to call again. */
	void apply(Player player)
	{
		// First time, or the game has reset the animations (e.g. after the teleport): capture them afresh.
		if (saved == null || player.getIdlePoseAnimation() != walk)
		{
			saved = new int[]{
				player.getIdlePoseAnimation(),
				player.getWalkAnimation(),
				player.getRunAnimation(),
				player.getIdleRotateLeft(),
				player.getIdleRotateRight(),
				player.getWalkRotateLeft(),
				player.getWalkRotateRight(),
				player.getWalkRotate180(),
			};
			walk = saved[1];
		}

		player.setIdlePoseAnimation(walk);
		player.setWalkAnimation(walk);
		player.setRunAnimation(walk);
		player.setIdleRotateLeft(walk);
		player.setIdleRotateRight(walk);
		player.setWalkRotateLeft(walk);
		player.setWalkRotateRight(walk);
		player.setWalkRotate180(walk);
		hold(player);
	}

	/** Makes sure the walk is showing this frame (the game can switch the pose back between ticks). */
	void hold(Player player)
	{
		if (saved == null)
		{
			return;
		}
		if (player.getPoseAnimation() != walk)
		{
			player.setPoseAnimation(walk);
			player.setPoseAnimationFrame(0);
		}
	}

	/** Puts the player's own animations back. */
	void restore(Player player)
	{
		if (player != null && saved != null)
		{
			player.setIdlePoseAnimation(saved[0]);
			player.setWalkAnimation(saved[1]);
			player.setRunAnimation(saved[2]);
			player.setIdleRotateLeft(saved[3]);
			player.setIdleRotateRight(saved[4]);
			player.setWalkRotateLeft(saved[5]);
			player.setWalkRotateRight(saved[6]);
			player.setWalkRotate180(saved[7]);
			player.setPoseAnimation(saved[0]);
			player.setPoseAnimationFrame(0);
		}
		saved = null;
		walk = -1;
	}

	/** Forgets without touching the player (after logout or a world hop). */
	void forget()
	{
		saved = null;
		walk = -1;
	}
}

package com.tabletportals;

import java.awt.AlphaComposite;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a picture of the other end in the portal's swirl, like a reflection on choppy water. The picture is
 * laid over the swirl's outline on screen, so it follows the portal as it opens, closes and turns with the
 * camera. Your character walking in front of the portal is kept in front of the reflection.
 */
class ReflectionOverlay extends Overlay
{
	/** Points around the rim of the swirl used to find its outline on screen. */
	private static final int RIM_POINTS = 32;
	/** The picture fills a little less than the swirl, so the swirl's edge still shows around it. */
	private static final float INSET = 0.86f;
	/** The biggest the reflection is drawn, in pixels; bigger is scaled up (keeps it cheap when zoomed in). */
	private static final int MAX_DRAW = 256;

	private final Client client;
	private final TabletPortalsConfig config;
	private final long startNanos = System.nanoTime();

	private Portal portal;
	private LocalPoint at;
	private int plane;
	private int orientation;
	private BufferedImage picture;
	private Walker walker;

	/** The picture scaled to the last drawn size, and a reusable frame buffer. */
	private int[] scaled;
	private int scaledW;
	private int scaledH;
	private BufferedImage frame;

	@Inject
	ReflectionOverlay(Client client, TabletPortalsConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	/** Shows {@code picture} in {@code portal}; {@code walker} (may be null) is kept in front of it. */
	void show(Portal portal, LocalPoint at, int plane, int orientation, BufferedImage picture, Walker walker)
	{
		this.portal = portal;
		this.at = at;
		this.plane = plane;
		this.orientation = orientation;
		this.walker = walker;
		if (this.picture != picture)
		{
			this.picture = picture;
			scaled = null;
		}
	}

	void hide()
	{
		portal = null;
		picture = null;
		walker = null;
		scaled = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Portal p = portal;
		if (p == null || picture == null || at == null || !config.reflection())
		{
			return null;
		}
		float radius = p.radius() * INSET;
		if (radius < 8f)
		{
			return null;
		}

		Polygon rim = rim(p, radius);
		if (rim == null)
		{
			return null;
		}
		Rectangle box = rim.getBounds();
		if (box.width < 6 || box.height < 6)
		{
			return null;
		}

		Area clip = new Area(rim);
		Shape inFront = walkerInFront();
		if (inFront != null)
		{
			clip.subtract(new Area(inFront));
		}

		// Render the ripple at up to MAX_DRAW pixels and let Java scale it the rest of the way.
		float shrink = Math.min(1f, MAX_DRAW / (float) Math.max(box.width, box.height));
		int w = Math.max(8, Math.round(box.width * shrink));
		int h = Math.max(8, Math.round(box.height * shrink));
		if (scaled == null || scaledW != w || scaledH != h)
		{
			scaled = WaterRipple.scaled(picture, w, h);
			scaledW = w;
			scaledH = h;
		}
		float seconds = (System.nanoTime() - startNanos) / 1e9f;
		float strength = config.reflectionStrength() / 100f * Math.min(1f, p.getSize());
		frame = WaterRipple.frame(scaled, w, h, seconds, config.ripple(), strength, frame);

		Shape oldClip = g.getClip();
		Composite oldComposite = g.getComposite();
		Object oldInterp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.clip(clip);
		g.setComposite(AlphaComposite.SrcOver);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(frame, box.x, box.y, box.width, box.height, null);
		g.setClip(oldClip);
		g.setComposite(oldComposite);
		if (oldInterp != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterp);
		}
		return null;
	}

	/** The swirl's outline on screen: a circle in the portal's plane, projected. */
	private Polygon rim(Portal p, float radius)
	{
		int centre = p.centreHeight();
		Polygon poly = new Polygon();
		for (int i = 0; i < RIM_POINTS; i++)
		{
			double a = i * Math.PI * 2 / RIM_POINTS;
			int side = (int) Math.round(Math.cos(a) * radius);
			int up = (int) Math.round(Math.sin(a) * radius);
			int[] d = Facing.right(orientation, side);
			LocalPoint lp = new LocalPoint(at.getX() + d[0], at.getY() + d[1], at.getWorldView());
			Point s = Perspective.localToCanvas(client, lp, plane, centre + up);
			if (s == null)
			{
				return null;
			}
			poly.addPoint(s.getX(), s.getY());
		}
		return poly;
	}

	/** Your character's outline on screen, if they're between the camera and the portal. */
	private Shape walkerInFront()
	{
		Walker wk = walker;
		if (wk == null || !wk.isShown())
		{
			return null;
		}
		LocalPoint w = wk.getLocation();
		if (w == null)
		{
			return null;
		}
		long camX = client.getCameraX();
		long camY = client.getCameraY();
		long toWalker = sq(w.getX() - camX) + sq(w.getY() - camY);
		long toPortal = sq(at.getX() - camX) + sq(at.getY() - camY);
		if (toWalker >= toPortal)
		{
			return null; // behind the portal: the reflection covers them, which is right
		}

		// A rough body outline facing the camera, a bit generous so no reflection spills over the character.
		double vx = w.getX() - camX;
		double vy = w.getY() - camY;
		double len = Math.max(1, Math.sqrt(vx * vx + vy * vy));
		double px = -vy / len;
		double py = vx / len;
		int[][] body = {{-50, 0}, {50, 0}, {60, 110}, {45, 225}, {-45, 225}, {-60, 110}};
		Polygon poly = new Polygon();
		for (int[] b : body)
		{
			LocalPoint lp = new LocalPoint((int) Math.round(w.getX() + px * b[0]),
				(int) Math.round(w.getY() + py * b[0]), w.getWorldView());
			Point s = Perspective.localToCanvas(client, lp, plane, b[1]);
			if (s == null)
			{
				return null;
			}
			poly.addPoint(s.getX(), s.getY());
		}
		return poly;
	}

	private static long sq(long v)
	{
		return v * v;
	}
}

